export function createSetupServer(missing){return http.createServer((req,res)=>{const p=new URL(req.url,'http://localhost').pathname;if(p==='/api/health'){res.writeHead(200,{'Content-Type':'application/json','Cache-Control':'no-store'});return res.end(JSON.stringify({ok:true,mode:'setup_required',missing}));}if(p.startsWith('/api/')){res.writeHead(503,{'Content-Type':'application/json','Cache-Control':'no-store'});return res.end(JSON.stringify({error:'Trung tâm đang hoàn tất kết nối dữ liệu. Vui lòng quay lại sau.'}));}res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'"});res.end('<!doctype html><html lang="vi"><meta name="viewport" content="width=device-width,initial-scale=1"><meta charset="utf-8"><title>Cổng giáo dục — Đang cấu hình</title><style>body{margin:0;background:#eff6ff;font:16px/1.7 system-ui,sans-serif;color:#1e293b;display:grid;min-height:100vh;place-items:center}main{max-width:540px;margin:24px;padding:36px;background:white;border:1px solid #dbeafe;border-radius:20px}small{color:#64748b}h1{font-size:26px;line-height:1.3;color:#1d4ed8}b{display:block;color:#2563eb;font-size:13px;letter-spacing:.05em}p{font-size:15px}</style><main><b>THẦY BÙI VĂN ĐƯỢC</b><h1>Cổng thông tin giáo dục</h1><p>Website đang hoàn tất kết nối dữ liệu của trung tâm.</p><p>Học sinh và phụ huynh vui lòng quay lại sau khi nhận được thông báo từ trung tâm.</p><small>Giám đốc: hoàn tất các biến môi trường trong Render để mở cổng đăng nhập.</small></main></html>');});}
async function configuredStore(env){if(env.SUPABASE_URL){const {createSupabaseStore}=await import('./supabase-store.mjs');return createSupabaseStore({url:env.SUPABASE_URL.trim(),key:env.SUPABASE_SERVICE_ROLE_KEY.trim(),initialState:emptyState(env.ADMIN_PASSWORD)});}let store,pool;const {Pool}=await import('pg');pool=new Pool({connectionString:env.DATABASE_URL,max:5});await pool.query('CREATE TABLE IF NOT EXISTS portal_state (id integer PRIMARY KEY, data jsonb NOT NULL)');await pool.query('CREATE TABLE IF NOT EXISTS portal_files (id text PRIMARY KEY, name text NOT NULL, type text NOT NULL, kind text NOT NULL, owner text NOT NULL, data bytea NOT NULL)');await pool.query('INSERT INTO portal_state (id,data) VALUES (1,$1) ON CONFLICT DO NOTHING',[JSON.stringify(emptyState(env.ADMIN_PASSWORD))]);store={read:async()=>clone((await pool.query('SELECT data FROM portal_state WHERE id=1')).rows[0].data),mutate:async(fn)=>{const client=await pool.connect();try{await client.query('BEGIN');const current=(await client.query('SELECT data FROM portal_state WHERE id=1 FOR UPDATE')).rows[0].data;const value=fn(current);await client.query('UPDATE portal_state SET data=$1 WHERE id=1',[JSON.stringify(value)]);await client.query('COMMIT');return clone(value)}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}},putFile:async f=>{await pool.query('INSERT INTO portal_files (id,name,type,kind,owner,data) VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING',[f.id,f.name,f.type,f.kind,f.owner,f.data])},getFile:async id=>(await pool.query('SELECT * FROM portal_files WHERE id=$1',[id])).rows[0]};store.close=()=>pool.end();return store;}
export async function startHostedPortal({env=process.env,initializeStore=configuredStore,port=Number(env.PORT||3000),host='0.0.0.0',retryDelayMs=10000}={}){
 const missing=['SESSION_SECRET','ADMIN_PASSWORD',...(env.SUPABASE_URL?['SUPABASE_SERVICE_ROLE_KEY']:['DATABASE_URL'])].filter(k=>!env[k]);
 if(env.SESSION_SECRET&&env.SESSION_SECRET.length<32)missing.push('SESSION_SECRET (32+ characters)');
 if(env.ADMIN_PASSWORD&&env.ADMIN_PASSWORD.length<12)missing.push('ADMIN_PASSWORD (12+ characters)');
 if(missing.length){const server=createSetupServer(missing);await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(port,host,resolve)});console.log('Portal setup pending: '+missing.join(', '));return {server,ready:Promise.resolve(false),close:()=>new Promise(r=>server.close(r))};}
 let actual=null,stopped=false,retryTimer=null,lastError='',resolveReady;const ready=new Promise(r=>resolveReady=r);
 const proxy={ready:()=>!!actual,status:()=>lastError,read:()=>{if(!actual)throw Error(lastError||'Đang kết nối dữ liệu, vui lòng thử lại sau.');return actual.read()},mutate:fn=>actual.mutate(fn),putFile:f=>actual.putFile(f),getFile:id=>actual.getFile(id)};
 const server=createPortalServer({env,store:proxy});
 await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(port,host,resolve)});
 console.log('Portal listening on '+host+':'+server.address().port+'; initializing database.');
 const initialize=async()=>{try{const result=await initializeStore(env);await result.read();if(stopped){await result.close?.();return;}actual=result;lastError='';console.log('Portal database ready.');resolveReady(true);}catch(e){if(stopped)return;lastError=e.message;console.error('Portal database initialization failed: '+e.message);retryTimer=setTimeout(initialize,retryDelayMs);retryTimer.unref?.();}};
 // Bind the HTTP port before any remote connection or password hashing.
 void Promise.resolve().then(initialize);
 const close=async()=>{stopped=true;clearTimeout(retryTimer);resolveReady(false);await new Promise(r=>server.close(r));await actual?.close?.();};
 return {server,ready,close};
}
async function main(){const portal=await startHostedPortal();process.on('SIGTERM',()=>portal.close().then(()=>process.exit(0)));}

if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))main().catch(e=>{console.error(e.message);process.exit(1)});

export function deleteCenterClass(d,m,{classId}={}){const c=d.classes.find(c=>c.id===classId);if(!c||!m||!['admin','teacher'].includes(m.role)||!classesFor(d,m).some(c=>c.id===classId))throw Error('Không có quyền xóa lớp này.');for(const s of [...c.students])deleteCenterStudent(d,m,{classId,sbd:s.sbd});d.classes=d.classes.filter(c=>c.id!==classId);for(const k of ['timetable','notifications','gradeBook','assignments','learningSubmissions','learningAttempts','learningReports','lessonProgress'])d[k]=d[k].filter(r=>r.classId!==classId);d.enrollmentApplications=d.enrollmentApplications.filter(a=>a.classId!==classId&&a.proposedClassId!==classId);for(const l of d.centerLessons)l.classIds=(l.classIds||[]).filter(id=>id!==classId);d._revision++;return d;}
export function regradeExam(d,m,{examId}={}){const ex=d.learningExams.find(e=>e.id===examId);if(!m||!['teacher','admin'].includes(m.role)||!ex||m.role==='teacher'&&ex.owner!==m.username)throw Error('Không có quyền cập nhật đáp án đề này.');const allowed=new Set(classesFor(d,m).map(c=>c.id)),assignments=d.assignments.filter(a=>a.examId===examId&&!a.archivedAt);if(assignments.some(a=>!allowed.has(a.classId)))throw Error('Đề có lớp chưa được phân công cho tài khoản này.');for(const a of assignments){const codes=examCodes(ex);if(codes.length&&[...d.learningSubmissions,...d.learningAttempts].some(t=>t.assignmentId===a.id&&t.examCode&&!codes.includes(t.examCode)))throw Error('Không thể bỏ mã đề đã có bài làm.');const used=d.learningSubmissions.some(s=>s.assignmentId===a.id)||d.learningAttempts.some(t=>t.assignmentId===a.id);if(used&&(a.snapshot.questions.length!==ex.questions.length||a.snapshot.questions.some((q,i)=>q.id!==ex.questions[i].id||q.type!==ex.questions[i].type)))throw Error('Đề đã có bài làm: chỉ sửa đáp án, thang điểm; giữ nguyên số câu và loại câu.');}for(const a of assignments){a.snapshot=clone(ex);delete a.snapshot.answerAttachment;delete a.snapshot.answerNotes;for(const old of d.learningSubmissions.filter(s=>s.assignmentId===a.id)){const scored=scoreSubmission(d,a,old,true);for(const q of a.snapshot.questions.filter(q=>q.type==='essay')){const previous=old.details.find(t=>t.qid===q.id),row=scored.details.find(t=>t.qid===q.id);if(previous?.points!==null&&previous?.points!==undefined){row.points=Math.min(q.points,previous.points);row.comment=previous.comment||'';}}scored.score=+scored.details.reduce((n,r)=>n+(r.points||0),0).toFixed(2);scored.status=scored.details.some(r=>r.points===null)?'pending':'graded';Object.assign(old,{details:scored.details,score:scored.score,status:scored.status,regradedAt:new Date().toISOString()});recordGrade(d,old);}}d._revision++;return d;}
export function batchGrade(d,m,{assignmentId,rows}={}){const a=d.assignments.find(a=>a.id===assignmentId);if(!a||!m||!['admin','teacher'].includes(m.role)||!classesFor(d,m).some(c=>c.id===a.classId))throw Error('Không có quyền chấm lớp này.');if(!Array.isArray(rows)||!rows.length||rows.length>5000)throw Error('Tải tối đa 5000 bài mỗi lần.');const c=d.classes.find(c=>c.id===a.classId),seen=new Set();for(const r of rows){if(!r||!c.students.some(s=>s.sbd===r.sbd)||seen.has(r.sbd)||!Array.isArray(r.answers)||r.answers.length!==a.snapshot.questions.length||r.answers.some(v=>typeof v!=='string'||v.length>10000))throw Error('SBD trùng, không có trong lớp hoặc số câu không khớp.');const qs=a.snapshot.answerVariants?.[String(r.examCode||a.snapshot.presentation?.code||'101')]||a.snapshot.questions;if(r.essayScores!==undefined&&(typeof r.essayScores!=='object'||Object.entries(r.essayScores).some(([i,n])=>!/^\d+$/.test(i)||qs[Number(i)]?.type!=='essay'||typeof n!=='number'||!Number.isFinite(n)||n<0||n>qs[Number(i)].points)))throw Error('Điểm tự luận không hợp lệ.');const code=String(r.examCode||a.snapshot.presentation?.code||'101');if(a.snapshot.answerVariants&&Object.keys(a.snapshot.answerVariants).length?!a.snapshot.answerVariants[code]:code!==String(a.snapshot.presentation?.code||'101')&&!a.snapshot.variantAttachments?.[code])throw Error('Chưa có đáp án cho mã đề '+code);seen.add(r.sbd);}for(const r of rows){const previous=d.learningSubmissions.find(s=>s.assignmentId===a.id&&s.classId===c.id&&s.sbd===r.sbd&&['teacher_batch','teacher_scan'].includes(s.source));const sub=scoreSubmission(d,a,{id:previous?.id||'batch_'+randomUUID(),assignmentId:a.id,classId:c.id,sbd:r.sbd,name:c.students.find(s=>s.sbd===r.sbd).name,attemptNo:previous?attemptNo(previous):nextAttemptNo(d,a,c.id,r.sbd),source:r.scanAttachment?'teacher_scan':'teacher_batch',examCode:String(r.examCode||a.snapshot.presentation?.code||'101'),scanAttachment:r.scanAttachment||previous?.scanAttachment,details:a.snapshot.questions.map((q,i)=>({qid:q.id,answer:r.answers[i]}))},true);for(const [i,n]of Object.entries(r.essayScores||{})){sub.details[Number(i)].points=n;sub.details[Number(i)].comment='Điểm tự luận do giáo viên nhập khi chấm phiếu.';}sub.score=+sub.details.reduce((n,q)=>n+(q.points||0),0).toFixed(2);sub.status=sub.details.some(q=>q.points===null)?'pending':'graded';if(previous)Object.assign(previous,sub);else d.learningSubmissions.push(sub);recordGrade(d,sub);}d._revision++;return d;}
